package com.gireesh.brokerage.entity;
import jakarta.persistence.*; import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="trade_plans", indexes={@Index(name="idx_plan_account",columnList="account_id"),@Index(name="idx_plan_security",columnList="security_id")})
public class TradePlan {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotNull @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="account_id",nullable=false) private TradingAccount account; @NotNull @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="security_id",nullable=false) private Security security; @NotNull @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private OrderSide side; @NotNull @PositiveOrZero @Digits(integer=18,fraction=6) @Column(nullable=false,precision=24,scale=6) private BigDecimal entryPrice; @NotNull @PositiveOrZero @Digits(integer=18,fraction=6) @Column(nullable=false,precision=24,scale=6) private BigDecimal stopPrice; @NotNull @PositiveOrZero @Digits(integer=18,fraction=6) @Column(nullable=false,precision=24,scale=6) private BigDecimal targetPrice; @NotNull @Positive private Integer quantity; @Size(max=2000) @Column(length=2000) private String thesis; @Column(nullable=false,updatable=false) private LocalDateTime createdAt; private LocalDateTime updatedAt;
 @PrePersist void create(){createdAt=LocalDateTime.now();updatedAt=createdAt;} @PreUpdate void update(){updatedAt=LocalDateTime.now();}
 public TradePlan(){} public Long getId(){return id;} public TradingAccount getAccount(){return account;} public void setAccount(TradingAccount v){account=v;} public Security getSecurity(){return security;} public void setSecurity(Security v){security=v;} public OrderSide getSide(){return side;} public void setSide(OrderSide v){side=v;} public BigDecimal getEntryPrice(){return entryPrice;} public void setEntryPrice(BigDecimal v){entryPrice=v;} public BigDecimal getStopPrice(){return stopPrice;} public void setStopPrice(BigDecimal v){stopPrice=v;} public BigDecimal getTargetPrice(){return targetPrice;} public void setTargetPrice(BigDecimal v){targetPrice=v;} public Integer getQuantity(){return quantity;} public void setQuantity(Integer v){quantity=v;} public String getThesis(){return thesis;} public void setThesis(String v){thesis=v;} public LocalDateTime getCreatedAt(){return createdAt;} public LocalDateTime getUpdatedAt(){return updatedAt;}
}